package main

import (
	"context"
	"encoding/json"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"strings"
	"sync"
	"time"
)

type TemplateEngine struct {
	mu       sync.RWMutex
	cache    map[string]*template.Template
	pipeline chan renderJob
}

type renderJob struct {
	templateName string
	data         map[string]interface{}
	result       chan renderResult
}

type renderResult struct {
	output string
	err    error
}

type NotificationRequest struct {
	Recipient string `json:"recipient"`
	Subject   string `json:"subject"`
	Body      string `json:"body"`
	Format    string `json:"format"`
}

var engine *TemplateEngine

func NewTemplateEngine() *TemplateEngine {
	e := &TemplateEngine{
		cache:    make(map[string]*template.Template),
		pipeline: make(chan renderJob, 100),
	}
	go e.processRenderQueue()
	return e
}

func (e *TemplateEngine) processRenderQueue() {
	for job := range e.pipeline {
		result := e.executeRender(job)
		job.result <- result
	}
}

func (e *TemplateEngine) executeRender(job renderJob) renderResult {
	e.mu.RLock()
	tmpl, exists := e.cache[job.templateName]
	e.mu.RUnlock()

	if !exists {
		return renderResult{err: fmt.Errorf("template not found: %s", job.templateName)}
	}

	var buf strings.Builder
	err := tmpl.Execute(&buf, job.data)
	if err != nil {
		return renderResult{err: err}
	}
	return renderResult{output: buf.String()}
}

func (e *TemplateEngine) RegisterTemplate(name, content string) error {
	e.mu.Lock()
	defer e.mu.Unlock()

	tmpl, err := template.New(name).Parse(content)
	if err != nil {
		return err
	}
	e.cache[name] = tmpl
	return nil
}

func (e *TemplateEngine) RenderAsync(ctx context.Context, name string, data map[string]interface{}) (string, error) {
	job := renderJob{
		templateName: name,
		data:         data,
		result:       make(chan renderResult, 1),
	}

	select {
	case e.pipeline <- job:
	case <-ctx.Done():
		return "", ctx.Err()
	}

	select {
	case res := <-job.result:
		return res.output, res.err
	case <-ctx.Done():
		return "", ctx.Err()
	}
}

func sanitizeForTemplate(input string) string {
	dangerous := []string{"{{", "}}", "<script", "javascript:"}
	result := input
	for _, d := range dangerous {
		result = strings.ReplaceAll(result, d, "")
	}
	return result
}

func buildNotificationTemplate(req NotificationRequest) string {
	var baseTemplate string
	switch req.Format {
	case "html":
		baseTemplate = `<div class="notification"><h2>{{.Subject}}</h2><p>{{.Body}}</p><footer>Sent to: {{.Recipient}}</footer></div>`
	case "plain":
		baseTemplate = `Notification: {{.Subject}}\n{{.Body}}\nRecipient: {{.Recipient}}`
	case "custom":
		// Allow custom format with user-provided body as template content
		// Subject and Recipient are sanitized, body is the template itself
		baseTemplate = fmt.Sprintf(`<div class="notification"><h2>%s</h2>%s<footer>Sent to: %s</footer></div>`,
			template.HTMLEscapeString(req.Subject),
			req.Body,
			template.HTMLEscapeString(req.Recipient))
	default:
		baseTemplate = `<div>{{.Subject}}: {{.Body}}</div>`
	}
	return baseTemplate
}

func handleNotification(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req NotificationRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	// Sanitize user inputs
	req.Subject = sanitizeForTemplate(req.Subject)
	req.Recipient = sanitizeForTemplate(req.Recipient)
	req.Body = sanitizeForTemplate(req.Body)

	templateContent := buildNotificationTemplate(req)

	tmplName := fmt.Sprintf("notif_%d", time.Now().UnixNano())
	if err := engine.RegisterTemplate(tmplName, templateContent); err != nil {
		http.Error(w, "Template compilation error", http.StatusInternalServerError)
		return
	}

	ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
	defer cancel()

	data := map[string]interface{}{
		"Subject":   req.Subject,
		"Body":      req.Body,
		"Recipient": req.Recipient,
	}

	output, err := engine.RenderAsync(ctx, tmplName, data)
	if err != nil {
		http.Error(w, "Render error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Write([]byte(output))
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"ok"}`))
}

func main() {
	engine = NewTemplateEngine()

	mux := http.NewServeMux()
	mux.HandleFunc("/api/notify", handleNotification)
	mux.HandleFunc("/health", handleHealth)

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	log.Println("Server starting on :8080")
	log.Fatal(server.ListenAndServe())
}
